export const recoveryRedirect=origin=>new URL('/?recovery=1',origin).href;
export function passwordProblem(password,confirmation){if(password.length<8)return 'Use pelo menos 8 caracteres.';if(password!==confirmation)return 'As senhas não coincidem.';return '';}
export async function sendRecovery(client,email,origin){const {error}=await client.auth.resetPasswordForEmail(email,{redirectTo:recoveryRedirect(origin)});if(error)throw error;}
export async function changePassword(client,password,confirmation){const problem=passwordProblem(password,confirmation);if(problem)throw new Error(problem);const {data,error}=await client.auth.getSession();if(error)throw error;if(!data.session)throw new Error('Link expirado ou inválido. Solicite outro e-mail de recuperação.');const result=await client.auth.updateUser({password});if(result.error)throw result.error;}
export function setupPasswordRecovery(getClient){
 const feedback=document.getElementById('sync-feedback'),email=document.getElementById('cloud-email'),button=document.getElementById('cloud-forgot');
 button.onclick=async()=>{if(!email.reportValidity())return;button.disabled=true;try{await sendRecovery(await getClient(),email.value.trim(),location.origin);feedback.textContent='Se houver uma conta para este e-mail, você receberá um link para redefinir a senha. Confira também o spam. Não crie outra conta.';}catch{feedback.textContent='Não foi possível solicitar a recuperação. Confira a conexão e aguarde alguns minutos antes de tentar novamente.';}finally{button.disabled=false;}};
 const url=new URL(location.href),hash=new URLSearchParams(url.hash.slice(1));
 if(url.searchParams.get('recovery')!=='1'&&hash.get('type')!=='recovery')return;
 const dialog=document.createElement('dialog');dialog.setAttribute('aria-labelledby','recovery-title');dialog.innerHTML='<form id="password-recovery-form"><h2 id="recovery-title">Definir nova senha</h2><p>Sua conta e suas caminhadas serão preservadas.</p><label class="fieldtitle" for="recovery-password">Nova senha</label><input id="recovery-password" type="password" minlength="8" autocomplete="new-password" required><label class="fieldtitle" for="recovery-confirm">Repita a nova senha</label><input id="recovery-confirm" type="password" minlength="8" autocomplete="new-password" required><p id="recovery-feedback" role="status">Validando seu link…</p><button class="primary" id="recovery-save" disabled>Salvar nova senha</button><button type="button" class="secondary" id="recovery-close">Fechar</button></form>';document.body.append(dialog);dialog.showModal();
 const status=dialog.querySelector('#recovery-feedback'),save=dialog.querySelector('#recovery-save');dialog.querySelector('#recovery-close').onclick=()=>dialog.close();
 let client;getClient().then(async c=>{client=c;const {data,error}=await c.auth.getSession();history.replaceState(null,'',location.pathname);if(error||!data.session)throw new Error('Este link expirou ou é inválido. Feche e solicite uma nova recuperação em Perfil.');save.disabled=false;status.textContent='Escolha uma senha com pelo menos 8 caracteres.';}).catch(e=>{status.textContent=e.message||'Não foi possível validar o link.';});
 dialog.querySelector('form').onsubmit=async e=>{e.preventDefault();save.disabled=true;try{await changePassword(client,dialog.querySelector('#recovery-password').value,dialog.querySelector('#recovery-confirm').value);dialog.querySelector('form').reset();status.textContent='Senha atualizada. Feche esta janela e entre com a nova senha.';feedback.textContent='Senha atualizada. Entre com seu e-mail e a nova senha.';}catch(e){status.textContent=e.message;save.disabled=false;}};
}
